mapper.select:
SELECT id, username, password_hash AS password, email, LOWER(role) AS role,
       usernum, classname, phone, department
FROM tap_user WHERE username = #{username}

SELECT id, username, password_hash AS password, email, LOWER(role) AS role,
       usernum, classname, phone, department
FROM tap_user WHERE id = #{id}

SELECT id, username, password AS password, email, LOWER(role) AS role,
       usernum, classname, phone, department
FROM user WHERE username = #{username}

SELECT id, username, password_hash AS password, email, LOWER(role) AS role,
       usernum, classname, phone, department
FROM tap_user WHERE usernum = #{usernum}
